candidates.raw:
    size_t i;
    adcs_vec3_t axis, term;
    double prod;
    adcs_status_t st;

    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) ||
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL)) {
        return ADCS_E_NULL;
    }
    if ((count < 1U) || (count > 16U) || (!isfinite(efficiency)) ||
        (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }
    st = adcs_wheel_momentum(wheels, count, momentum);
    if (st != ADCS_OK) {
        return ADCS_E_RANGE;
    }
    *body_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    *mechanical_power = 0.0;
    *bus_power = 0.0;
    for (i = 0; i < count; i++) {
        if (!isfinite(wheel_torque[i])) {
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
            return ADCS_E_RANGE;
        }
        term = adcs_vec3_scale(&axis, -wheel_torque[i]);
        *body_torque = adcs_vec3_add(body_torque, &term);
        prod = wheel_torque[i] * wheels[i].speed_rad_s;
        *mechanical_power += prod;
        if (prod > 0.0) {
            *bus_power += prod / efficiency;
        }
    }
    return ADCS_OK;
}

