    adcs_vec3_t h_vec, axis, term;
    double tau_x = 0.0, tau_y = 0.0, tau_z = 0.0;
    double p_mech = 0.0, p_bus = 0.0, u, omega, p;

    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) ||
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL))
        return ADCS_E_NULL;

    if ((count < 1U) || (count > 16U) || (!isfinite(efficiency)) ||
        (efficiency <= 0.0) || (efficiency > 1.0))
        return ADCS_E_RANGE;

    if (adcs_wheel_momentum(wheels, count, &h_vec) != ADCS_OK)
        return ADCS_E_RANGE;

    for (i = 0; i < count; i++) {
        if (!isfinite(wheel_torque[i]))
            return ADCS_E_RANGE;
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)
            return ADCS_E_RANGE;
        u = wheel_torque[i];
        omega = wheels[i].speed_rad_s;
        term = adcs_vec3_scale(&axis, u);
        tau_x -= term.x;
        tau_y -= term.y;
        tau_z -= term.z;
        p = u * omega;
        p_mech += p;
        if (p > 0.0)
            p_bus += p / efficiency;
    }

    *momentum = h_vec;
    body_torque->x = tau_x;
    body_torque->y = tau_y;
    body_torque->z = tau_z;
    *mechanical_power = p_mech;
    *bus_power = p_bus;
    return ADCS_OK;
}

